export interface SaveMasterRecordRequest {
	/** Create only (locked afterwards). tenant_type: ^[a-z][a-z0-9_]{1,49}$, institution: ^[a-z0-9_-]{3,50}$ (tenant code), grade_level: ^[A-Z0-9_]{1,20}$, user: email, permission & notification_template: ^[a-z][a-z0-9_]*(\.[a-z0-9_]+)+$, others: ^[A-Z0-9_]{2,20}$ */
	code?: string;
	/** @maxLength 100 */
	name: string;
	/** @maxLength 500 */
	description: string;
	status: MasterStatus;
	/**
	 * education_level, grade_level (required)
	 * @minimum 1
	 */
	sort_order?: number;
	/**
	 * curriculum
	 * @maxLength 50
	 */
	version?: string;
	subject_group?: MasterSubjectGroup;
	/** subject, grade_level (required); institution (optional) */
	education_level_code?: string;
	/** subject (optional) */
	curriculum_code?: string;
	/** institution (required) */
	tenant_type_code?: string;
	/** institution (required, unique) */
	email?: string;
	/** institution, user (optional, 8-16 digits) */
	phone?: string;
	data_region?: MasterDataRegion;
	/** institution */
	address?: string;
	/** academic_year (required) */
	start_date?: string;
	/** academic_year (required, after start_date) */
	end_date?: string;
	/** academic_year; saving true releases the previous current period */
	is_current?: boolean;
	account_kind?: MasterAccountKind;
	/** user (required) */
	tenant_code?: string;
	/** user (required) */
	role_code?: string;
	/** user */
	note?: string;
	scope?: MasterRoleScope;
	module?: MasterPermissionModule;
	action?: MasterPermissionAction;
	/** notification_template (at least one) */
	channels?: MasterNotificationChannel[];
	/**
	 * notification_template (required)
	 * @maxLength 200
	 */
	subject?: string;
	/**
	 * notification_template (required; variables nama_siswa, nama_tugas, tenggat, nama_kelas, nilai, nama_sekolah, kode_cluster, persen_terpakai, jumlah_db, maks_db, ambang)
	 * @maxLength 2000
	 */
	body?: string;
	/**
	 * cluster_region (e.g. ap-southeast-3a)
	 * @maxLength 100
	 */
	zone?: string;
	/** cluster_region (data stored outside Indonesia; UI shows a PDP warning) */
	outside_indonesia?: boolean;
	/** Required on update; must equal the stored value */
	updated_at?: string;
}

